SELECT ?predicate
       (COUNT(*) AS ?occurrences)
       (COUNT(DISTINCT ?s) AS ?subjects)
       (SAMPLE(?o) AS ?sample)
WHERE {
  GRAPH <https://lindas.admin.ch/foj/zefix> {
    ?s a <http://schema.org/PostalAddress> .
    ?s ?predicate ?o .
  }
}
GROUP BY ?predicate
ORDER BY DESC(?occurrences)
LIMIT 40

